"    // --- Client-Side Inactivity Watcher (15-Minute Auto-Logout) ---
    let idleTime = 0;
    const idleLimit = 900; // 15 minutes in seconds

    const resetIdleTimer = () => {
        idleTime = 0;
    };

    // Listen to standard activity events
    const activityEvents = ['mousemove', 'keypress', 'click', 'scroll', 'touchstart'];
    activityEvents.forEach(evt => {
        document.addEventListener(evt, resetIdleTimer, true);
    });

    // Check timer increment every second
