"def load_sops():
    sops = []
    try:
        conn = psycopg2.connect(DB_URL)
        with conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT doc_id as id, title, url_slug as file, category as department 
                FROM "HEX_ManualIndex"
            """)
            sops = cur.fetchall()
        conn.close()
    except Exception as e:
        print(f"FAILURE: load_sops database error. {e}")
        if os.path.exists(INDEX_FILE):
            with open(INDEX_FILE, 'r') as f:
                sops = json.load(f)

    # Sort the SOPs according to the order of appearance in qms_index.json (the source of truth)
    order_map = {}
    if os.path.exists(INDEX_FILE):
        try:
            with open(INDEX_FILE, 'r') as f:
                index_data = json.load(f)
                for index, item in enumerate(index_data):
                    order_map[item['id']] = index
        except Exception as e:
            print(f"FAILURE: load_sops index file read error. {e}")

    sops.sort(key=lambda x: order_map.get(x['id'], 999))

    sops_by_dept = {}
    for sop in sops:
        dept = sop.get('department', 'General')
        if dept not in sops_by_dept:
            sops_by_dept[dept] = []
        sops_by_dept[dept].append(sop)
    return sops_by_dept
"

